import React, { useState, useEffect } from "react";
import SockJS from "sockjs-client";
import Stomp from "stompjs";
import axios from "axios";

export default function Match({ userEmail }) {
  const [entryFee, setEntryFee] = useState(13);
  const [status, setStatus] = useState("");
  const [game, setGame] = useState(null);
  const [playerId, setPlayerId] = useState(null);

  const ALLOWED_FEES = [13, 23, 50];

  useEffect(() => {
    // কেবল যখন ম্যাচ শুরু হয়েছে তখন সংযোগ তৈরি করবো
    if (game?.id) {
      const socket = new SockJS("http://localhost:8080/ludo-ws");
      const stompClient = Stomp.over(socket);

      stompClient.connect({}, () => {
        stompClient.subscribe(`/topic/match/${game.id}`, (message) => {
          const gameSession = JSON.parse(message.body);
          setGame(gameSession);
          setStatus("🎮 Game started! Good luck!");
        });
      });

      return () => {
        stompClient.disconnect();
      };
    }
  }, [game?.id]);

  const handleMatchRequest = async () => {
    if (!ALLOWED_FEES.includes(Number(entryFee))) {
      setStatus("❌ Invalid entry fee. Only 13, 23, or 50 allowed.");
      return;
    }

    try {
      setStatus("⏳ Searching for opponent...");

      const response = await axios.post("http://localhost:8080/api/match/start", {
        entryFee,
        email: userEmail,
      });

      const data = response.data;

      if (data.gameId) {
        setStatus("🎉 Match found! Waiting to start game...");
        setGame({ id: data.gameId });
        setPlayerId(data.playerId);
      } else {
        setStatus("⌛ Waiting for opponent to join...");
      }
    } catch (err) {
      console.error(err);
      setStatus("⚠️ Error: " + err.response?.data?.message || "Unknown error");
    }
  };

  return (
    <div className="max-w-md mx-auto p-6 bg-white rounded shadow-md">
      <h2 className="text-xl font-bold mb-4 text-center">🕹️ Start Ludo Match</h2>

      <div className="mb-4">
        <label className="block text-sm font-medium text-gray-700 mb-1">Select Entry Fee:</label>
        <select
          value={entryFee}
          onChange={(e) => setEntryFee(Number(e.target.value))}
          className="w-full border border-gray-300 rounded px-3 py-2"
        >
          {ALLOWED_FEES.map((fee) => (
            <option key={fee} value={fee}>
              ৳ {fee}
            </option>
          ))}
        </select>
      </div>

      <button
        onClick={handleMatchRequest}
        className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-2 px-4 rounded"
      >
        🔍 Find Opponent
      </button>

      {status && (
        <p className="mt-4 text-center text-sm text-gray-700">
          <strong>Status:</strong> {status}
        </p>
      )}

      {game && game.id && (
        <div className="mt-6 text-center text-green-600">
          <p>✅ Game ID: {game.id}</p>
          <p>👤 You are Player: {playerId}</p>
        </div>
      )}
    </div>
  );
}
